import React, { useState } from "react";
import styled from "styled-components";
import FastaTable from "./Fasta";
import VirulenceTable from "./Virulence";
import AmrTable from "./Amr"; 

const Container = styled.div`
  margin-top: 10px;
  display: flex;
  justify-content: center;
`;

const Wrapper = styled.div`
  width: 90%;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ButtonGroup = styled.div`
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
`;

const Button = styled.button`
  padding: 10px 20px;
  background-color: ${(props) => (props.selected ? "#007bff" : "#f1f1f1")};
  color: ${(props) => (props.selected ? "#fff" : "#000")};
  border: 1px solid #ccc;
  border-radius: 5px;
  font-size: 16px;
  cursor: pointer;
  margin-right: 10px;

  &:hover {
    background-color: #0056b3;
    color: white;
  }

  &:last-child {
    margin-right: 0;
  }
`;

const Result = ({ fastaInfo, virulenceInfo, amrInfo }) => {
  const [selectedTab, setSelectedTab] = useState("Fasta");

  const handleTabClick = (tab) => {
    setSelectedTab(tab);
  };

  return (
    <Container>
      <Wrapper>
        <ButtonGroup>
          <Button
            selected={selectedTab === "Fasta"}
            onClick={() => handleTabClick("Fasta")}
          >
            Fasta
          </Button>
          <Button
            selected={selectedTab === "Virulence"}
            onClick={() => handleTabClick("Virulence")}
          >
            Virulence
          </Button>
          <Button
            selected={selectedTab === "AMR"}
            onClick={() => handleTabClick("AMR")}
          >
            AMR
          </Button>
        </ButtonGroup>

        {selectedTab === "Fasta" && <FastaTable sample={fastaInfo} />}
        {selectedTab === "Virulence" && <VirulenceTable data={virulenceInfo} />}
        {selectedTab === "AMR" && <AmrTable data={amrInfo} />}
      </Wrapper>
    </Container>
  );
};

export default Result;
